/bin/bash -lc "python - <<'PY'
import requests
for repo in ['biocontainers/openpyxl','biocontainers/python','biocontainers/pandas']:
    url=f'https://quay.io/api/v1/repository/{repo}/tag/?limit=5'
    try:
        r=requests.get(url, timeout=15)
        print(repo, r.status_code)
        if r.ok:
            data=r.json()
            for t in data.get('tags', [])[:5]:
                print(' ', t.get('name'))
    except Exception as e:
        print(repo, 'ERR', e)
PY"
